source='''from collections import Counter, deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue

            queue = deque([(r, c)])
            seen.add((r, c))
            component = []
            while queue:
                y, x = queue.popleft()
                component.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        queue.append((yy, xx))

            r0 = min(y for y, x in component)
            r1 = max(y for y, x in component)
            c0 = min(x for y, x in component)
            c1 = max(x for y, x in component)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            border = {
                (y, x)
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
                if y in (r0, r1) or x in (c0, c1)
            }
            if set(component) != border:
                continue

            interior_height = r1 - r0 - 1
            interior_width = c1 - c0 - 1
            fill = 7 if interior_height % 2 == 1 and interior_width % 2 == 1 else 2
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if grid[y][x] == background:
                        out[y][x] = fill

    return out
